"use client";import {useState} from "react";import {supabase} from "../lib/supabase-browser";
export default function Orders(){const [phone,setPhone]=useState(""),[orders,setOrders]=useState([]),[searched,setSearched]=useState(false);async function search(){setSearched(true);const {data}=await supabase().from("orders").select("*").eq("phone",phone).order("created_at",{ascending:false});setOrders(data||[])}const status=s=>({pending:"قيد المراجعة",confirmed:"تم التأكيد",preparing:"جاري التجهيز",shipped:"تم الشحن",delivered:"تم التسليم",cancelled:"ملغي"}[s]||s);return <main className="orders-page" dir="rtl"><header className="admin-top"><a href="/">شوبلي <small>SHOPLY</small></a><a href="/">الرئيسية</a></header><section className="orders-wrap"><span className="eyebrow">متابعة طلبك</span><h1>طلباتي</h1><p>اكتب رقم الهاتف المستخدم في الطلب.</p><div className="track-form"><input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="رقم الهاتف"/><button className="primary" onClick={search}>بحث</button></div>{searched&&!orders.length&&<div className="empty">لا توجد طلبات بهذا الرقم.</div>}{orders.map(o=><article className="order-card" key={o.id}><div><b>طلب #{o.id}</b><small>{new Date(o.created_at).toLocaleString("ar-EG")}</small></div><span>{status(o.status)}</span><strong>{Number(o.total).toLocaleString("ar-EG")} ج.م</strong></article>)}</section></main>}
